def board_card(b):
 return '<article class="card board-card">'+photo(b['photo'],b['name']+' · '+b['role'],cls='board-portrait')+'<p class="eyebrow">'+esc(b['role'])+'</p><h2>'+esc(b['name'])+'</h2><p class="board-company">'+esc(b['company'])+'</p>'+link('/bblo/members/'+b['member_slug']+'/', 'Profile &amp; contact details →','text-link')+'</article>'
board=hero('Meet our board','The people behind<br><em>the community.</em>','Meet the BBLO leadership team. Open a profile for business contact information and available website, Facebook and Instagram links.')+section('<div class="grid three board-grid">'+''.join(board_card(b) for b in board_data['members'])+'</div>')+section('<p class="eyebrow">Build the community with us</p><h2>Connect with BBLO.</h2><p>Interested in membership, a community activity or supporting local businesses? Let’s start a conversation.</p><div class="actions">'+link('/bblo/join/','How to join')+link('/bblo/support/','Feature your brand','button secondary')+'</div>','map-section')
page('/bblo/board/','Meet Our Board','Meet the BBLO leadership team members, their roles, photographs and business contact profiles.',board,'bblo/board/carmen-garcia-tirado.webp')

def field(label,name,kind='text',required=True,options=None):
 req=' required' if required else '';id='f-'+name
 if options:control=f'<select id="{id}" name="{name}"{req}><option value="">Choose…</option>'+''.join('<option>'+esc(x)+'</option>' for x in options)+'</select>'
 elif kind=='textarea':control=f'<textarea id="{id}" name="{name}"{req}></textarea>'
 else:control=f'<input id="{id}" name="{name}" type="{kind}"{req}>'
 return '<div class="form-field"><label for="'+id+'">'+label+(' *' if required else ' (optional)')+'</label>'+control+'</div>'
def identity(prefix):return field('Your name',prefix+'name')+field('Business name',prefix+'business')+field('Email',prefix+'email','email')
def form(title,id,content,permission='I agree that Carmen may contact me about this request.'):
 return '<article class="inquiry-form" id="'+id+'"><h2>'+title+'</h2><form class="bblo-review-form" onsubmit="return false"><div class="form-grid">'+content+'</div><label class="form-consent"><input type="checkbox" data-consent required>'+permission+'</label><button type="submit" class="button">Review my answers</button><p class="form-status">Review only — nothing is sent or saved.</p><div class="form-summary" tabindex="-1" role="status" hidden></div></form></article>'
def form_notice():return '<div class="review-note"><strong>Form preview.</strong> These forms do not send, save or publish information. Use sample details while reviewing.</div>'
win_types=['Introduction / referral','Business received','Collaboration','One-to-one','Community contribution','Milestone']
def winlist(id,optional=False):
 toggle='<label class="form-consent"><input type="checkbox" data-win-toggle data-ui>Add wins to this check-in</label>' if optional else ''
 checks=''.join('<label class="checkbox-option"><input type="checkbox" name="wins[__INDEX__][types]" value="'+esc(t)+'" data-win-type> '+t+'</label>' for t in win_types)
 item='<fieldset data-win-entry><legend>Win <span data-win-number>1</span></legend><p class="note">Choose every type that applies to this win. Add a separate entry for a different win.</p><div class="checkbox-grid">'+checks+'</div><div class="form-grid">'+field('Date of win',id+'-__INDEX__-date','date')+field('People or businesses involved',id+'-__INDEX__-people',required=False)+field('What happened?',id+'-__INDEX__-description','textarea')+field('Value in USD',id+'-__INDEX__-value','number',False)+field('Supporting link',id+'-__INDEX__-link','url',False)+field('Sharing preference',id+'-__INDEX__-sharing',options=['Private tracking only','Contact me to approve a public story'])+'</div><button type="button" class="text-button" data-remove-win>Remove this win</button></fieldset>'
 return '<div class="win-builder" data-win-builder>'+toggle+'<div data-win-area'+(' hidden' if optional else '')+'><div data-win-list></div><button type="button" class="button secondary" data-add-win>Add another win</button><p class="note" data-win-count aria-live="polite"></p></div><template data-win-template>'+item+'</template></div>'
visitor=form('Visitor check-in','visitor-check-in',identity('visitor-')+field('Phone','visitor-phone','tel',False)+field('Meeting date','visitor-date','date')+field('Business category','visitor-category')+field('Visit','visitor-type',options=['First visit','Returning visitor'])+field('Who invited you?','visitor-referral',required=False)+field('Preferred language','visitor-language',required=False,options=['English','Español','Either']))
